using UnityEngine;
// Direction-aware stepping layered after locomotion: planted feet stay in world space.
[DefaultExecutionOrder(220)]
public class WoodlandCombatFeet:MonoBehaviour {
 public WoodlandHostile hostile;public float plantedTravelError{get;private set;}
 class Leg{public Transform hip,knee,foot;public Vector3 rest,plant,from,to;public Quaternion rotation;public float progress=1;public bool moving;public Quaternion h,k,f;}
 Leg left,right;Vector3 previous;bool ready,posed;int next;float ankleHeight=.25f;
 Transform Bone(string n){foreach(var t in GetComponentsInChildren<Transform>())if(t.name.EndsWith(":"+n))return t;return null;}
 Leg Make(string side){var l=new Leg{hip=Bone(side+"UpLeg"),knee=Bone(side+"Leg"),foot=Bone(side+"Foot")};if(!l.hip||!l.knee||!l.foot)return null;l.rest=transform.InverseTransformPoint(l.foot.position);l.rotation=Quaternion.Inverse(transform.rotation)*l.foot.rotation;l.plant=Ground(l.foot.position);return l;}
 void Start(){if(!hostile)hostile=GetComponent<WoodlandHostile>();var lf=Bone("LeftFoot");var rf=Bone("RightFoot");if(lf&&rf)ankleHeight=Mathf.Clamp(Mathf.Min(lf.position.y,rf.position.y)-WoodlandCompanion.Ground(transform.position.x,transform.position.z),.06f,.4f);left=Make("Left");right=Make("Right");previous=transform.position;ready=left!=null&&right!=null;}
 Vector3 Ground(Vector3 p){foreach(var hit in Physics.RaycastAll(p+Vector3.up*.45f,Vector3.down,1.1f,~0,QueryTriggerInteraction.Ignore)){if(hit.collider.transform.IsChildOf(transform)||hit.normal.y<.6f)continue;p.y=hit.point.y+ankleHeight;return p;}p.y=WoodlandCompanion.Ground(p.x,p.z)+ankleHeight;return p;}
 void Update(){if(!ready||!posed||!hostile||!hostile.anatomy)return;if(!hostile.anatomy.Incapacitated){foreach(var l in new[]{left,right}){l.hip.localRotation=l.h;l.knee.localRotation=l.k;l.foot.localRotation=l.f;}}posed=false;}
 void LateUpdate(){Step(Time.deltaTime);}
 public void Step(float delta){if(!ready||!hostile||!hostile.anatomy||hostile.anatomy.Incapacitated||!hostile.animator.enabled)return;var injury=GetComponent<WoodlandNPCInjury>();if(injury&&injury.HoldsPosition){previous=transform.position;return;}float dt=Mathf.Max(delta,.001f);Vector3 velocity=(transform.position-previous)/dt;previous=transform.position;velocity.y=0;if(velocity.magnitude>6){left.plant=Ground(left.foot.position);right.plant=Ground(right.foot.position);left.moving=right.moving=false;velocity=Vector3.zero;}float speed=velocity.magnitude;
 if(!left.moving&&!right.moving){var l=next==0?left:right;Vector3 desired=Ground(transform.TransformPoint(l.rest)+velocity*.1f);Vector3 error=desired-l.plant;error.y=0;if(error.magnitude>(speed>.15f?.11f:.22f)){l.from=l.plant;l.to=desired;l.progress=0;l.moving=true;next=1-next;}}
 foreach(var l in new[]{left,right}){l.h=l.hip.localRotation;l.k=l.knee.localRotation;l.f=l.foot.localRotation;Vector3 target=l.plant;if(l.moving){float duration=Mathf.Lerp(.28f,.18f,Mathf.Clamp01(speed/2.5f));l.progress=Mathf.Min(1,l.progress+dt/duration);float u=l.progress*l.progress*(3-2*l.progress);target=Vector3.Lerp(l.from,l.to,u);float lift=Mathf.Lerp(.035f,.095f,hostile.anatomy.MovementMultiplier);target.y+=Mathf.Sin(l.progress*Mathf.PI)*lift;if(l.progress>=1){l.plant=l.to;l.moving=false;target=l.plant;}}Solve(l,target);if(!l.moving)plantedTravelError=Mathf.Max(plantedTravelError,Vector3.Distance(l.foot.position,l.plant));}posed=true;}
 void Solve(Leg l,Vector3 target){Vector3 root=l.hip.position,joint=l.knee.position;float a=Vector3.Distance(root,joint),b=Vector3.Distance(joint,l.foot.position);Vector3 axis=(target-root).normalized;float d=Mathf.Clamp(Vector3.Distance(root,target),.03f,a+b-.003f);Vector3 bend=Vector3.ProjectOnPlane(transform.forward,axis).normalized;float along=(a*a+d*d-b*b)/(2*d);Vector3 knee=root+axis*along+bend*Mathf.Sqrt(Mathf.Max(0,a*a-along*along));l.hip.rotation=Quaternion.FromToRotation(joint-root,knee-root)*l.hip.rotation;l.knee.rotation=Quaternion.FromToRotation(l.foot.position-l.knee.position,target-l.knee.position)*l.knee.rotation;l.foot.rotation=transform.rotation*l.rotation;}
}
